from collections import deque

class N:
    def __init__(s, v, l=None, r=None):
        s.val, s.left, s.right = v, l, r

def bfs(root):
    if not root:
        return []
    q, out = deque([root]), []
    while q:
        for _ in range(len(q)):   # 本层快照
            node = q.popleft(); out.append(node.val)
            if node.left:  q.append(node.left)
            if node.right: q.append(node.right)
    return out

print(bfs(N(1, N(2), N(3))))   # [1, 2, 3]

